import { Routes } from "@angular/router";
import { ExamType } from "./exam-type/exam-type";
import { ExamTypeAdd } from "./exam-type/exam-type-add/exam-type-add";
import { Grade } from "./grade/grade";
import { Result } from "./result/result";
import { ResultAdd } from "./result/result-add/result-add";
import { RoutezFeatureModule } from "@_core/_route";
import { Exam } from "./exam/exam";
import { ExamAdd } from "./exam/exam-add/exam-add";
import { GradeAdd } from "./grade/grade-add/grade-add";
import { ExamSubjectz } from "./exam-subjectz/exam-subjectz";
import { ExamSubjectzAdd } from "./exam-subjectz/exam-subjectz-add/exam-subjectz-add";

export const Routez: Routes = new RoutezFeatureModule(
  'Exam',
  'feature/exam'
)
.feature(
  ExamType,
  ExamTypeAdd,
  'exam-type',
  'Exam Type'
)
.feature(
  Exam,
  ExamAdd,
  'exam',
  'Exam'
)
.feature(
  ExamSubjectz,
  ExamSubjectzAdd,
  'exam-subject',
  'Exam Subject'
)
.feature(
  Grade,
  GradeAdd,
  'grade',
  'Grade'
)
.feature(
  Result,
  ResultAdd,
  'result',
  'Result'
)
.build();
