import { BaseClassTemplate } from '@_core/__base';
import { URL_CONTRL, URL_SRVC } from '@_core/_client';
import { TM_List } from '@_core/_pagination';
import {
  ChangeDetectionStrategy,
  Component,
  OnInit,
  ViewEncapsulation,
} from '@angular/core';

@Component({
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'aam-exam-subjectz',
  templateUrl: './exam-subjectz.html',
})
export class ExamSubjectz extends BaseClassTemplate implements OnInit {
  ngOnInit() {
    this.initTables();
  }
  initTables() {
    this._template.lb = new TM_List(this,
      {
        srvc: URL_SRVC.Edu,
        cntrl: URL_CONTRL.Edu.ExamSubjectz,
      },
      [
        { key: 'examId', name: 'Exam' },
        { key: 'subjectzId', name: 'Subject' },
        { key: 'marksTotal', name: 'Total Marks' },
        { key: 'marksPassing', name: 'Passing Marks' },
        { key: 'dateExam', name: 'Exam Date' },
        { key: 'timeStart', name: 'Start Time' },
        { key: 'timeEnd', name: 'End Time' },
      ]
    ).init();
  }
}
