import { BaseClassTemplate } from '@_core/__base';
import { URL_CONTRL, URL_SRVC } from '@_core/_client';
import { TM_List } from '@_core/_pagination';
import {
  ChangeDetectionStrategy,
  Component,
  OnInit,
  ViewEncapsulation,
} from '@angular/core';

@Component({
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'aam-result',
  templateUrl: './result.html',
})
export class Result extends BaseClassTemplate implements OnInit {
  ngOnInit() {
    this.initTables();
  }
  initTables() {
    this._template.lb = new TM_List(this,
      {
        srvc: URL_SRVC.Edu,
        cntrl: URL_CONTRL.Edu.Result,
      },
      [
        { key: 'userStudentId', name: 'Student' },
        { key: 'examSubjectzId', name: 'Exam Subject' },
        { key: 'obtainMarks', name: 'Marks' },
        { key: 'grade', name: 'Grade' },
        { key: 'remarks', name: 'Remarks' },
      ]
    ).init();
  }
}
