import { BaseClassSrvc } from "@_core/__base";
import { FormDesc, FormId } from "@_core/_form";

export function MyForm(that: BaseClassSrvc, d: any = {}) {
  that._fs._form = that._fb.group({
    ...FormId(that, d),
    ...FormDesc(that, d),
    userStudentId: [d?.userStudentId || '', that._vs._val('Student')],
    examSubjectzId: [d?.examSubjectzId || '', that._vs._val('Exam Subject')],
    grade: [d?.grade || ''],
    marksObtain: [d?.marksObtain || '', that._vs._val('Obtain Marks')],
  });
}
