import { BaseClassTemplate } from '@_core/__base';
import { URL_CONTRL, URL_SRVC } from '@_core/_client';
import { TM_List } from '@_core/_pagination';
import {
  ChangeDetectionStrategy,
  Component,
  OnInit,
  ViewEncapsulation,
} from '@angular/core';

@Component({
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'aam-exam',
  templateUrl: './exam.html',
})
export class Exam extends BaseClassTemplate implements OnInit {
  ngOnInit() {
    this.initTables();
  }
  initTables() {
    this._template.lb = new TM_List(this,
      {
        srvc: URL_SRVC.Edu,
        cntrl: URL_CONTRL.Edu.Exam,
      },
      [
        { key: 'examTypeId', name: 'Exam Type' },
        { key: 'termId', name: 'Term' },
        { key: 'startDate', name: 'Start Date' },
        { key: 'endDate', name: 'End Date' },
        { key: 'totalMarks', name: 'Total Marks' },
        { key: 'passingMarks', name: 'Passing Marks' },
      ]
    ).init();
  }
}
