import { BaseClassSrvc } from "@_core/__base";
import { FormBase } from "@_core/_form";

export function MyForm(that: BaseClassSrvc, d: any = {}) {
  that._fs._form = that._fb.group({
    ...FormBase(that, d),
    examId: [d?.examId || ''],
    subjectzId: [d?.subjectzId || ''],
    marksTotal: [d?.marksTotal || ''],
    marksPassing: [d?.marksPassing || ''],
    dateExam: [d?.dateExam || ''],
    timeStart: [d?.timeStart || ''],
    timeEnd: [d?.timeEnd || ''],
  });
}
